import { change_directory_of_owner_ship } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    tranferOwnerDialog: Boolean,
    rowInfo: Object,
    allusers: Array
  },
  data() {
    return {
      selectUser: "",
      userItems: [],
      loading: false
    };
  },
  watch: {
    tranferOwnerDialog: {
      async handler() {
        if (this.tranferOwnerDialog == true) {
          this.userItems = [];
          this.allusers.forEach(element => {
            if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT" && element.user_email_id != this.rowInfo.directory_created_by) {
              this.userItems.push({
                full_user_name: element.full_user_name,
                user_email_id: element.user_email_id
              });
            }
          });
        }
      },
      immediate: true
    }
  },
  methods: {
    async validate_data() {
      const {
        valid
      } = await this.$refs.forms.validate();
      if (valid) {
        this.transfer_ownership();
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      if (this.$refs.forms) {
        this.$refs.forms.reset();
      }
    },
    async transfer_ownership() {
      this.loading = true;
      var userId = [];
      userId.push(this.rowInfo.user_id);
      // console.log(this.entryInfo.responseObject.directory_id);
      try {
        let result = await API.graphql(graphqlOperation(change_directory_of_owner_ship, {
          input: {
            directory_id: this.rowInfo.directory_id,
            user_email_id: this.selectUser
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.change_directory_of_owner_ship);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
